from solution import multiply_int


def test_issue_example_10_20():
    """Example requires multiply 10 by 20 to give 200."""
    assert multiply_int(10, 20) == 200  # 10 x 20 = 200


def test_issue_small_positives():
    """Multiply two positive integers gives product."""
    assert multiply_int(3, 4) == 12  # 3 x 4 = 12


def test_issue_zero_left():
    """Zero times any integer gives zero."""
    assert multiply_int(0, 7) == 0  # 0 x 7 = 0


def test_issue_zero_right():
    """Any integer times zero gives zero."""
    assert multiply_int(7, 0) == 0  # 7 x 0 = 0


def test_issue_both_zero():
    """Zero times zero gives zero."""
    assert multiply_int(0, 0) == 0  # 0 x 0 = 0


def test_issue_negative_times_positive():
    """Negative times positive gives negative product."""
    assert multiply_int(-3, 4) == -12  # -3 x 4 = -12


def test_issue_positive_times_negative():
    """Positive times negative gives negative product."""
    assert multiply_int(5, -6) == -30  # 5 x -6 = -30


def test_issue_negative_times_negative():
    """Negative times negative gives positive product."""
    assert multiply_int(-4, -5) == 20  # -4 x -5 = 20


def test_issue_one_identity():
    """Any integer times one equals itself."""
    assert multiply_int(9, 1) == 9  # 9 x 1 = 9


def test_issue_large_numbers():
    """Large integers multiply to full product."""
    assert multiply_int(123, 456) == 56088  # 123 x 456 = 56088


def test_contract_callable():
    """Public interface provides multiply_int in solution module."""
    assert callable(multiply_int)  # callable check for multiply_int


def test_contract_returns_int():
    """Public interface returns integer product for integer inputs."""
    assert isinstance(multiply_int(2, 3), int)  # 2 x 3 = 6 is int
